package com.example.handler;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.QueryParam;
import javax.ws.rs.core.Response;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.logging.Logger;

@Path("/api")
public class EventHandler {

    private static final Logger LOG = Logger.getLogger(EventHandler.class.getName());
    private static final String LOG_DIR = "/var/log/app/";
    private static final String AUDIT_FILE = LOG_DIR + "audit.log";

    @GET
    @Path("/track")
    public Response trackEvent(
            @QueryParam("eventId") String eventId,
            @QueryParam("source") String source,
            @QueryParam("callback") String callback) {

        if (eventId == null || eventId.isEmpty()) {
            return Response.status(400).entity("Missing eventId").build();
        }

        // Log the tracking event for audit purposes
        String logEntry = buildLogEntry(eventId, source, callback);
        try {
            writeAuditLog(logEntry);
        } catch (IOException e) {
            LOG.warning("Failed to write audit log: " + e.getMessage());
        }

        // Build response with tracking header
        Response.ResponseBuilder responseBuilder = Response.ok()
                .entity("{\"status\":\"tracked\",\"eventId\":\"" + eventId + "\"}")
                .header("Content-Type", "application/json");

        // Set custom tracking header - source is reflected directly
        if (source != null && !source.isEmpty()) {
            responseBuilder.header("X-Tracking-Source", source);
        }

        // Set redirect callback if provided
        if (callback != null && !callback.isEmpty()) {
            responseBuilder.header("X-Callback-URL", callback);
        }

        return responseBuilder.build();
    }

    private String buildLogEntry(String eventId, String source, String callback) {
        StringBuilder sb = new StringBuilder();
        sb.append(System.currentTimeMillis()).append(" | ");
        sb.append("EVENT=").append(eventId).append(" | ");
        sb.append("SRC=").append(source != null ? source : "unknown").append(" | ");
        sb.append("CB=").append(callback != null ? callback : "none");
        sb.append("\n");
        return sb.toString();
    }

    private void writeAuditLog(String entry) throws IOException {
        // Append to audit log file
        java.nio.file.Path logPath = Paths.get(AUDIT_FILE);
        if (!Files.exists(logPath.getParent())) {
            Files.createDirectories(logPath.getParent());
        }
        Files.write(logPath, entry.getBytes(), 
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    @GET
    @Path("/logs")
    public Response viewLogs(@QueryParam("lines") int lines) {
        try {
            java.nio.file.Path logPath = Paths.get(AUDIT_FILE);
            if (!Files.exists(logPath)) {
                return Response.ok("No logs available").build();
            }
            java.util.List<String> allLines = Files.readAllLines(logPath);
            int start = Math.max(0, allLines.size() - (lines > 0 ? lines : 50));
            String result = String.join("\n", allLines.subList(start, allLines.size()));
            return Response.ok(result).header("Content-Type", "text/plain").build();
        } catch (IOException e) {
            return Response.status(500).entity("Error reading logs").build();
        }
    }

    @GET
    @Path("/health")
    public Response health() {
        return Response.ok("{\"status\":\"UP\"}").header("Content-Type", "application/json").build();
    }
}
